    "landing.faq.a1": "Diamond Education markazida guruhlarda sifat va samaradorlikni saqlab qolish maqsadida o'quvchilar soni 10–12 kishidan oshmasligi belgilangan. Bu har bir talabaga individual e'tibor qaratish imkonini beradi.",
    "landing.faq.q2": "Darslar qayerda va qachon bo'lib o'tadi?",
    "landing.faq.a2": "Bizning filiallarimiz qulay transport yo'nalishlarida joylashgan: 1-filialimiz birinchi poliklinika ro'parasida, 2-filialimiz esa yangi ko'prikka yetmay Havas do'konining yuqori qavatida joylashgan. Guruhlarimiz ertalabki, tushlikdan keyingi va kechki vaqtlarga mo'ljallangan bo'lib, o'quvchi o'ziga qulay bo'lgan vaqtni tanlashi mumkin.",
    "landing.faq.q3": "To'lovlarni qanday va qaysi shaklda amalga oshirish mumkin?",
    "landing.faq.a3": "To'lovlarni istalgan qulay shaklda — naqd pul va milliy to'lov tizimlari Click, Payme, Uzum Bank kabi ilovalar orqali amalga oshirishingiz mumkin. Shuningdek, 1 oylik yoki butun kurs uchun oldindan to'lov imkoniyati mavjud.",
    "landing.faq.q4": "O'qituvchi mos kelmasa, uni almashtirish mumkinmi?",
    "landing.faq.a4": "Ha. Bizning ommaviy ofertamizda ko'rsatilganidek, har bir o'quvchi o'zining o'qituvchisi mos kelmagan holatda uni almashtirishi mumkin.",
    "landing.faq.q5": "Darslarga sababli tarzda kelmay qolinsa nima bo'ladi? Sababli holatlarga nimalar kiradi?",
    "landing.faq.a5": "Sababli holatlarga bizda asosan kasallik varaqasi ko'rsatilgandagina o'quvchi kelmagan darsi uchun to'lov qilmaydi. Boshqa holatlarda darsga qatnashish majburiy hisoblanadi.",
    "landing.faq.q6": "O'quv markazingizdagi ingliz tili o'qituvchilari darajalari qanday?",
    "landing.faq.a6": "Bizning o'quv markazimizda yuqori malakali va xalqaro sertifikatlarga ega o'qituvchilar dars o'tadi. Ularning IELTS natijalari 7.0 dan 8.5 gacha oralig'ida joylashgan.",
    "landing.faq.q7": "O'quv markazida darsdan tashqari shug'ullanish uchun sharoitlar, qo'shimcha xonalar va Support o'qituvchilar bormi?",
    "landing.faq.a7": "Albatta. O'quvchilarimizga maksimal qulaylik va sifatli ta'limni ta'minlash maqsadida har ikki filialimizda ham Support o'qituvchilar bor. Ular bilan siz maxsus ajratilgan xonalarda shug'ullanishingiz mumkin.",
    "landing.about.kicker": "BIZNING FALSAFA VA MISSIYA",
    "about.subtitle": "Eng yaxshi kelajak shu yerdan boshlanadi",
    "landing.about.title": "Premium Integratsiyalashgan Ta'lim Ekotizimi",
    "landing.about.description": "Diamond Education – bu shunchaki o'quv markazi emas, balki innovatsion ta'lim muhitidir. Biz zamonaviy raqamli metodlar, doimiy tahlil va monitoring tizimi orqali har bir bilim oluvchining salohiyatini maksimal darajada ochib beramiz.",
    "landing.about.value1.title": "Jahon Standartlaridagi Dasturlar",
    "landing.about.value1.desc": "Bizning metodikamiz va o'quv materiallarimiz xalqaro talablarga mos keladi hamda muntazam yangilanib boradi.",
    "landing.about.value2.title": "Adaptiv Ta'lim Traektoriyasi",
    "landing.about.value2.desc": "Platforma har bir bilim oluvchining individual o'sish dinamikasini tahlil qilib, unga moslashtirilgan vazifa va testlarni taqdim etadi.",
    "landing.about.value3.title": "Yagona Sinxron Tizim",
    "landing.about.value3.desc": "Web-portal, shaxsiy kabinet va Telegram-bot yagona ma'lumotlar bazasida ishlaydi. Davomat, ballar va o'zlashtirish real vaqtda yangilanadi.",
