    "landing.callback.successDesc": "Скоро наш оператор свяжется с вами.",
    "landing.branches.title": "Наши филиалы",
    "landing.branches.subtitle": "Посетите один из двух наших удобно расположенных филиалов и запишитесь на бесплатный пробный урок.",
    "landing.branches.branch1": "1-й Филиал",
    "landing.branches.branch2": "2-й Филиал",
    "landing.branches.map": "Посмотреть на карте",
    "landing.cta.kicker": "НАЧНИТЕ СВОЙ ПРОФЕССИОНАЛЬНЫЙ РОСТ",
    "landing.cta.title": "Сделайте уверенный шаг в будущее вместе с Diamond Education",
    "landing.footer.about": "Премиальная образовательная платформа, основанная на передовых технологиях и проверенных методиках.",
    "landing.footer.rights": "Все права защищены.",
    "landing.footer.oferta": "Публичная оферта",
    "landing.faq.title": "Часто задаваемые вопросы",
    "landing.faq.subtitle": "Ответы на наиболее часто задаваемые вопросы о нашем учебном центре.",
    "landing.faq.q1": "Сколько студентов в группе?",
    "landing.faq.a1": "В Diamond Education количество учащихся в группах не превышает 10–12 человек, чтобы сохранить качество и эффективность обучения. Это позволяет уделять каждому студенту индивидуальное внимание.",
    "landing.faq.q2": "Где и когда проходят занятия?",
    "landing.faq.a2": "Наши филиалы расположены в удобных транспортных узлах: 1-й филиал — напротив первой поликлиники, 2-й филиал — на верхнем этаже магазина Havas, не доезжая до нового моста. Группы рассчитаны на утреннее, дневное и вечернее время, студент может выбрать удобное время.",
    "landing.faq.q3": "Как и в каком виде можно произвести оплату?",
    "landing.faq.a3": "Оплату можно произвести в любом удобном виде — наличными или через национальные платёжные системы Click, Payme, Uzum Bank. Также доступна предоплата на 1 месяц или за весь курс.",
    "landing.faq.q4": "Можно ли сменить преподавателя, если он не подходит?",
    "landing.faq.a4": "Да. Согласно нашей публичной оферте, каждый студент имеет право сменить своего преподавателя, если тот ему не подходит.",
    "landing.faq.q5": "Что происходит, если пропустить занятие по уважительной причине? Что считается уважительной причиной?",
    "landing.faq.a5": "Уважительной причиной в нашем центре считается в первую очередь предоставление больничного листа — в этом случае студент не оплачивает пропущенное занятие. В остальных случаях посещение является обязательным.",
    "landing.faq.q6": "Каков уровень преподавателей английского языка в вашем центре?",
    "landing.faq.a6": "В нашем учебном центре занятия ведут высококвалифицированные преподаватели с международными сертификатами. Результаты IELTS наших преподавателей находятся в диапазоне от 7.0 до 8.5.",
    "about.founder.name": "Акбарходжа Анварходжаев",
    "about.founder.role": "Основатель и Генеральный директор",
    "about.founder.title": "Строим светлое будущее вместе",
    "about.founder.quote1": "Образование — это не только передача знаний, но и передача уверенности молодым людям, помощь им в совершении первого шага к большим целям в их сознании.",
    "about.founder.quote2": "При создании центра Diamond Education нашей главной целью было создание качественной среды и системы, которая максимально раскроет возможности каждого ученика. Независимо от того, насколько велика цель, ее можно достичь при правильной подготовке и сильной команде.",
    "landing.faq.q7": "Есть ли в вашем центре условия для занятий вне урока, дополнительные комнаты и Support-преподаватели?",
    "landing.faq.a7": "Конечно. В целях обеспечения максимального комфорта и качественного образования для наших студентов в обоих филиалах работают Support-преподаватели. Вы можете заниматься с ними в специально отведённых помещениях.",
    "landing.about.kicker": "НАША ФИЛОСОФИЯ И МИССИЯ",
    "about.subtitle": "Лучшее будущее начинается здесь",
    "landing.about.title": "Интегрированная Премиум-Экосистема Обучения",
    "landing.about.description": "Diamond Education – это больше чем учебный центр. Мы создаем инновационную среду, в которой сочетаются современные технологии и лучшие методики преподавания для полного раскрытия потенциала каждого студента.",
    "landing.about.value1.title": "Программы Мирового Класса",
    "landing.about.value1.desc": "Наши учебные материалы соответствуют международным стандартам и регулярно обновляются.",
    "landing.about.value2.title": "Адаптивная Траектория Развития",
    "landing.about.value2.desc": "Платформа анализирует индивидуальные показатели каждого ученика, подбирая персональные тесты и задания.",
    "landing.about.value3.title": "Единая Синхронная Система",
    "landing.about.value3.desc": "Сайт, личный кабинет и Telegram-бот работают на общей базе. Данные об успеваемости и баллах доступны в реальном времени.",
    "splash.subtitle": "Единая платформа Telegram Mini App и Web",
