    "landing.cta.kicker": "EMBARK ON YOUR PROFESSIONAL PATHWAY",
    "landing.cta.title": "Step confidently into your future with Diamond Education",
    "landing.footer.about": "Premium EdTech academy utilizing advanced interactive technologies and proven methodologies.",
    "landing.footer.rights": "All rights reserved.",
    "landing.footer.oferta": "Public Offer",
    "landing.faq.title": "Frequently Asked Questions",
    "landing.faq.subtitle": "Answers to the most frequently asked questions about our education centre.",
    "landing.faq.q1": "How many students are in each group?",
    "landing.faq.a1": "At Diamond Education, group sizes are capped at 10–12 students to maintain quality and effectiveness. This ensures every student receives individual attention.",
    "landing.faq.q2": "Where and when are classes held?",
    "landing.faq.a2": "Our branches are located in convenient transport hubs: Branch 1 is opposite the first polyclinic, Branch 2 is on the top floor of the Havas store just before the new bridge. Groups are scheduled for morning, afternoon and evening slots so students can choose the most convenient time.",
    "landing.faq.q3": "How and in what form can payments be made?",
    "landing.faq.a3": "Payments can be made in any convenient form — cash or through national payment systems such as Click, Payme, and Uzum Bank. Advance payment for 1 month or the full course is also available.",
    "landing.faq.q4": "Is it possible to change a teacher if they are not a good fit?",
    "landing.faq.a4": "Yes. As stated in our public offer agreement, every student has the right to change their teacher if they feel it is not the right match.",
    "landing.faq.q5": "What happens if a class is missed for a valid reason? What counts as a valid reason?",
    "landing.faq.a5": "A valid reason in our centre is primarily a medical certificate — in this case the student does not pay for the missed lesson. In all other cases, attendance is mandatory.",
    "landing.faq.q6": "What is the qualification level of English teachers at your centre?",
    "landing.faq.a6": "Our centre employs highly qualified teachers holding international certificates. The IELTS scores of our teachers range from 7.0 to 8.5.",
    "about.founder.name": "Akbarxo'ja Anvarxo'jayev",
    "about.founder.role": "Founder and CEO",
    "about.founder.title": "Building a bright future together",
    "about.founder.quote1": "Education is not only about imparting knowledge, but also about sharing confidence with young people, helping them take the first step towards big goals in their minds.",
    "about.founder.quote2": "When creating the Diamond Education center, our main goal was to create a quality environment and system that maximizes the potential of each student. No matter how big the goal is, it can be reached with the right preparation and a strong team.",
    "landing.faq.q7": "Are there facilities for self-study outside of class, including extra rooms and Support teachers?",
    "landing.faq.a7": "Absolutely. To provide maximum comfort and quality education for our students, both branches have dedicated Support teachers. You can study with them in specially allocated rooms.",
    "landing.about.kicker": "OUR ETHOS AND VISION",
    "about.subtitle": "The best future begins here",
    "landing.about.title": "Premium Integrated Educational Ecosystem",
    "landing.about.description": "Diamond Education is more than a standard tutoring school. We create a dynamic, tech-enhanced educational environment that combines modern digital tools with premium mentorship to unlock each student's full potential.",
    "landing.about.value1.title": "Global Academic Benchmarks",
    "landing.about.value1.desc": "Our methodologies and resources match international guidelines and undergo continuous updates.",
    "landing.about.value2.title": "Adaptive Development Blueprints",
    "landing.about.value2.desc": "The platform analyzes individual progress data to dynamically deliver personalized testing and resources.",
