function normalizeLiteralText(value: string) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

const LITERAL_UI_LOOKUP: Record<string, LiteralEntry> = (() => {
  const lookup: Record<string, LiteralEntry> = {};
  for (const entry of LITERAL_UI_TEXT) {
    for (const value of Object.values(entry)) {
      const key = normalizeLiteralText(value);
      if (key) lookup[key] = entry;
    }
  }
  return lookup;
})();

function translateLiteralValue(value: string, locale: Locale) {
  const normalized = normalizeLiteralText(value);
  if (!normalized || normalized.length > 260) return null;
  const entry = LITERAL_UI_LOOKUP[normalized];
  if (!entry) return null;
  return entry[locale] || entry.uz;
}

const DOM_I18N_ATTRS = ["placeholder", "title", "aria-label", "alt"];
const DOM_I18N_SKIP_SELECTOR = "script,style,noscript,code,pre,textarea,[data-no-dom-i18n],[data-i18n-ignore]";

function shouldSkipDomI18n(node: Node) {
  const element = node.nodeType === Node.ELEMENT_NODE
    ? node as Element
    : node.parentElement;
  if (!element) return true;
  return Boolean(element.closest(DOM_I18N_SKIP_SELECTOR));
}

function localizeTextNode(node: Text, locale: Locale) {
  if (shouldSkipDomI18n(node)) return;
  const raw = node.nodeValue || "";
  const translated = translateLiteralValue(raw, locale);
  if (!translated) return;
  const prefix = raw.match(/^\s*/)?.[0] || "";
  const suffix = raw.match(/\s*$/)?.[0] || "";
  const next = `${prefix}${translated}${suffix}`;
  if (next !== raw) node.nodeValue = next;
}

function localizeElementAttributes(element: Element, locale: Locale) {
  if (shouldSkipDomI18n(element)) return;
  for (const attr of DOM_I18N_ATTRS) {
    const value = element.getAttribute(attr);
    if (!value) continue;
    const translated = translateLiteralValue(value, locale);
    if (translated && translated !== value) element.setAttribute(attr, translated);
  }
}

function localizeDomTree(root: ParentNode | Node, locale: Locale) {
  if (typeof document === "undefined") return;
  if (root.nodeType === Node.TEXT_NODE) {
    localizeTextNode(root as Text, locale);
    return;
  }
  if (root.nodeType !== Node.ELEMENT_NODE && root.nodeType !== Node.DOCUMENT_NODE) return;
  const elementRoot = root as Element | Document;
  if (elementRoot instanceof Element) {
    localizeElementAttributes(elementRoot, locale);
  }
  const walker = document.createTreeWalker(elementRoot, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  let current: Node | null = walker.currentNode;
  while (current) {
    if (current.nodeType === Node.TEXT_NODE) {
      localizeTextNode(current as Text, locale);
    } else if (current.nodeType === Node.ELEMENT_NODE) {
      localizeElementAttributes(current as Element, locale);
    }
    current = walker.nextNode();
  }
  if (document.title) {
    const translatedTitle = translateLiteralValue(document.title, locale);
    if (translatedTitle && translatedTitle !== document.title) document.title = translatedTitle;
  }
}

function useDomLiteralI18n(locale: Locale) {
  useEffect(() => {
    if (typeof window === "undefined" || typeof document === "undefined") return;
    document.documentElement.lang = locale;
    let frame = 0;
    const run = (root: ParentNode | Node = document.body) => {
      if (!root) return;
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => localizeDomTree(root, locale));
    };
    run(document.body);
    const observer = new MutationObserver((mutations) => {
      const roots: Node[] = [];
      for (const mutation of mutations) {
        if (mutation.type === "attributes") {
          roots.push(mutation.target);
        } else {
          mutation.addedNodes.forEach((node) => roots.push(node));
        }
      }
      if (!roots.length) return;
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => {
        for (const node of roots.slice(0, 60)) {
          localizeDomTree(node, locale);
        }
      });
    });
    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: DOM_I18N_ATTRS,
    });
    return () => {
      observer.disconnect();
      window.cancelAnimationFrame(frame);
    };
  }, [locale]);
}

function interpolate(template: string, params?: Params) {
  if (!params) return template;
  return template.replace(/\{(\w+)\}/g, (_, k: string) => String(params[k] ?? `{${k}}`));
}

export function resolveLocale(value?: string | null): Locale {
  const low = String(value || "").trim().toLowerCase();
  if (low === "ru" || low === "en" || low === "uz") return low;
  return "uz";
}

export function t(locale: Locale, key: string, fallback?: string, params?: Params): string {
  const localized = EXTRA_MESSAGES[locale]?.[key] || WEB_MESSAGES[locale]?.[key];
  const uzFallback = EXTRA_MESSAGES.uz[key] || WEB_MESSAGES.uz[key];
  const final = localized || uzFallback || fallback || key;
  return interpolate(final, params);
}

const WebLocaleContext = createContext<Locale>("uz");

export function WebLocaleProvider({ locale, children }: { locale: Locale; children: ReactNode }) {
  useDomLiteralI18n(locale);
  return <WebLocaleContext.Provider value={locale}>{children}</WebLocaleContext.Provider>;
}

export function RootWebLocaleProvider({ children }: { children: ReactNode }) {
  const [locale, setLocale] = useState<Locale>("uz");

  useEffect(() => {
    if (typeof window === "undefined") return;
    const apply = (value?: string | null) => {
      const next = resolveLocale(value || localStorage.getItem("diamond_locale") || document.documentElement.lang || "uz");
      setLocale(next);
      localStorage.setItem("diamond_locale", next);
      document.documentElement.lang = next;
    };
    apply();
    const onLocaleEvent = (event: Event) => {
      const detail = (event as CustomEvent<{ locale?: string }>).detail || {};
      apply(detail.locale);
    };
    window.addEventListener("diamond:locale-change", onLocaleEvent as EventListener);
    return () => window.removeEventListener("diamond:locale-change", onLocaleEvent as EventListener);
  }, []);

  return <WebLocaleProvider locale={locale}>{children}</WebLocaleProvider>;
}

export function useWebLocale() {
  return useContext(WebLocaleContext);
}

export function useWebT() {
  const locale = useWebLocale();
  return useCallback((key: string, fallback?: string, params?: Params) => t(locale, key, fallback, params), [locale]);
}

export function sectionLabelByLocale(section: string, locale: Locale, fallback?: string) {
  return t(locale, `section.${section}`, fallback || section);
}
